環境工学は「建物の中の空気・熱・光・湿気をどう快適に保つか」を扱う分野です。
・換気＝汚れた空気を入れ替える技術
・伝熱＝熱が壁を通って逃げる／入るしくみ
・結露＝空気中の水蒸気が冷えて水滴になる現象
