×「第3種換気は室内が正圧になる」→誤り。排気のみ機械なので負圧
×「南面の日射受熱量は夏が最大」→誤り。鉛直壁の南面は冬が最大
×「中空層は厚いほど断熱性が上がる」→誤り。2〜4cm程度で頭打ち

