構造力学は「建物にかかる力（荷重）を骨組がどう受け止めるか」を計算する学問です。
・荷重→梁や柱に「曲げ」「せん断」「軸力」が生じる
・部材が力に耐えられるかは「断面の形」と「材料の強さ」で決まる
