・コンクリートのヤング係数：圧縮強度・単位容積質量が大きいほど大きい
・中性化：CO₂によりアルカリ性喪失→鉄筋の不動態被膜が破壊され腐食リスク
・アルカリ骨材反応：反応性骨材＋アルカリ＋水分で膨張ひび割れ

【図解】水セメント比と品質の関係
項目｜水セメント比が小さい｜水セメント比が大きい
