・アルカリ骨材反応：骨材が膨張→ひび割れ
・凍害：水分凍結膨張→表面剥離
○対策の共通原則：水セメント比を小さく・かぶりを確保・ひび割れを抑える

━━━━━━━━━━━━━━━━━━━━━━
