　・その先で応力がほとんど増えないままひずみだけ伸びる点が降伏点。
　・さらにひずみが進むと応力は再び上昇し、曲線の頂点が引張強さ。
　・頂点を過ぎると応力が下がりながら伸び、やがて破断する。
○降伏点を超えると力を除いてもひずみが残る（塑性変形）
→「降伏比が小さい＝降伏後の粘り（変形能力）が大きい」

