        body: `▼ゼロから　構造形式の全体地図
建物の骨組には、RC造・S造のラーメン構造のほかに、壁で支える壁式構造、
木の軸組、PC鋼材で圧縮をかけるプレストレスト構造などがあります。
それぞれ「何で力に抵抗するか」を一言で言えるようにするのが第一歩です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 鉄骨構造の接合部
━━━━━━━━━━━━━━━━━━━━━━
・柱脚形式：露出型・根巻き型・埋込み型（固定度：埋込み＞根巻き＞露出）
・ベースプレートのアンカーボルト：ナット上に3山以上の余長を確保
・仕口：通しダイアフラム形式・内ダイアフラム形式・外ダイアフラム形式
　→ ダイアフラムは梁フランジの応力を柱に伝える力の通り道
・トラス構造：三角形の骨組で構成し、各部材には軸力（引張・圧縮）のみが生じる

【図解】柱脚3形式の固定度
・露出型：ベースプレートを基礎の上に露出させて固定する形式（固定度：小）
・根巻き型：柱脚まわりをRCで根巻きして補強する形式（固定度：中）
・埋込み型：柱を基礎コンクリートに埋め込む形式（固定度：大）
→固定度が大きいほど柱脚に曲げを負担させられる（剛接合に近い）

━━━━━━━━━━━━━━━━━━━━━━
🔑 壁式鉄筋コンクリート構造
━━━━━━━━━━━━━━━━━━━━━━
・柱・梁がなく、耐力壁と床版で構成する構造（住宅系に多い）
・耐力壁の厚さ・配筋量に構造規定がある（中高層は特に厳格）
・階数・高さに制限がある（一般に5階建て程度まで、壁式ラーメン構造で緩和）
・耐力壁の量（壁量）を平面上の各方向にバランスよく配置する
・開口部が大きいと耐力壁の性能が下がるため開口周比の規定がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 木造建築物
━━━━━━━━━━━━━━━━━━━━━━
・在来軸組構法：柱・梁の軸組で骨組を構成し、筋かい等で水平力に抵抗する
・枠組壁工法（ツーバイフォー）：規格化された枠組みと面材で構成する
・耐力壁の壁倍率：筋かい・構造用合板等の種類により定められる
・筋かいの断面：圧縮筋かいは厚さ3cm以上×幅9cm以上、
　引張筋かいは厚さ1.5cm以上×幅9cm以上
・筋かいをたすき掛けにする場合は相互の欠込み禁止（片方をボルト等で補強）
・接合部：金物（羽子板ボルト・ホールダウン金物等）で緊結する
　→ ホールダウン金物は柱の引抜き防止（浮き上がり対策）

【図解】木造の水平力抵抗要素
　・柱と横架材で囲まれた四角い軸組の中に、対角線状に斜め材を入れたものが筋かい。
　・同じ位置に構造用合板を張り、面で抵抗させたものが面材耐力壁。
○地震力・風圧力は耐力壁が負担→壁量計算で必要量を確認
○耐力壁は建物の平面にバランスよく（偏心を小さく）配置する
×「筋かいは多いほど良いので1箇所に集中配置」→偏心が生じ誤り

【図解】圧縮筋かいと引張筋かいの断面規定
・引張筋かい：厚さ1.5cm以上×幅9cm以上
・圧縮筋かい：厚さ3cm以上×幅9cm以上
→圧縮材は座屈するため、より厚い断面が必要（座屈と結びつけて暗記）

━━━━━━━━━━━━━━━━━━━━━━
🔑 プレストレストコンクリート（PC）構造
━━━━━━━━━━━━━━━━━━━━━━
・PC鋼材にあらかじめ引張力を導入し、コンクリートに圧縮力を与える
　→ 荷重による引張応力を打ち消し、ひび割れを抑制できる
・プレテンション方式（先引き：工場製品向き）・
　ポストテンション方式（後引き：現場施工向き）
・大スパンの梁・床版に適する

【図解】プレストレスの原理
　通常のRC梁：荷重で下側に引張→ひび割れが生じやすい
　　＿＿＿＿＿＿＿＿
　　￣￣＼＿＿／￣￣　←下端に引張ひび割れ
　PC梁：PC鋼材の緊張力で下端にあらかじめ圧縮を導入
　　←●━━━━━●→　（PC鋼材が梁を締め付ける）
　　→荷重による引張を圧縮が打ち消し、ひび割れを抑制
⇒本の列を両側から強く挟むと持ち上げられるのと同じ原理
→プレテンション＝コンクリート打込み「前」に鋼材を緊張（工場）
→ポストテンション＝硬化「後」にシース内の鋼材を緊張（現場）

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「露出柱脚が最も固定度が高い」→誤り。埋込み型が最も高い
×「トラス部材には曲げモーメントが生じる」→誤り。原則軸力のみ
×「圧縮筋かいは厚さ1.5cm以上でよい」→誤り。3cm以上（座屈のため）
×「アンカーボルトの余長はナット上1山でよい」→誤り。3山以上
×「壁式RC構造には階数の制限がない」→誤り。高さ・階数に制限あり

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★柱脚固定度：埋込み＞根巻き＞露出／アンカーボルト余長3山以上
★筋かい：圧縮3cm×9cm・引張1.5cm×9cm、たすき掛けの欠込み禁止
★ホールダウン金物＝柱の引抜き防止
★PC構造：プレテンション＝工場、ポストテンション＝現場
★トラス＝軸力のみ、壁式＝壁量と配置バランス

━━━━━━━━━━━━━━━━━━━━━━
🔑 深掘り：木造軸組工法の耐震要素
━━━━━━━━━━━━━━━━━━━━━━
・壁量計算：地震力に対して必要な壁量（地震力用）と、
　風圧力に対して必要な壁量（風圧力用）をそれぞれ満たすように
　耐力壁（筋かい・面材耐力壁等）を配置する
・四分割法：建物の平面を東西・南北それぞれ4分割し、
　両端の側端部分における必要壁量に対する存在壁量の
　充足率（壁率比）を確認することで、耐力壁の
　偏った配置（ねじれやすさ）を防ぐ考え方
・N値計算法：柱に生じる引抜き力を柱の位置・
　周囲の耐力壁の状況等から算定し、
　その引抜き力に見合う柱頭・柱脚の接合金物を選定する方法
・出隅の柱・耐力壁端部の柱ほど大きな引抜き力を
　受けやすく、より強固な接合金物（ホールダウン金物等）が必要になる

【図解】木造軸組工法の耐震チェックの流れ
　平面計画（耐力壁の配置検討）
　　↓
　壁量計算（地震力用・風圧力用それぞれ充足を確認）
　　↓
　四分割法（側端部分の壁率比でバランスを確認）
　　↓
　N値計算法（柱ごとの接合金物を選定）
→「量」「バランス」「接合部」の3段階でチェックする

【図解】柱の引抜き力と接合金物の対応
・引抜き力が小さい柱：かど金物等の比較的簡易な金物
・引抜き力が大きい柱：ホールダウン金物等の強固な金物
→出隅・耐力壁端部の柱ほど大きな引抜き力を受けやすい`,
