・トータルステーション（TS）：角度に加え
　距離も同時に測定できる機器。1台で
　座標（位置）を直接求められるため、
　効率的な測量が可能
・GNSS測量：衛星からの電波を利用して
　位置を測定する方法。広範囲の測量や
　見通しの悪い場所での補完的な活用が進んでいる

