        id: 'gaku-10',
        title: '構造計算の応用（座屈・地震荷重・音の合成）',
        emoji: '🧮',
        body: `▼ゼロから　計算問題の攻略法
応用問題は「公式に数値を入れて比べる」形式がほとんどです。
公式の丸暗記ではなく「何に比例し、何に反比例するか」を押さえると、
数値が変わっても比率で解けます。ここでは頻出3テーマの計算の型を示します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 座屈（オイラーの座屈荷重）
━━━━━━━━━━━━━━━━━━━━━━
・弾性座屈荷重 Pcr＝π²EI／lk²（lk：座屈長さ）
　→ 座屈長さ lk の2乗に反比例する（座屈長さが長いほど座屈荷重は小さい）
　→ ヤング係数E・断面二次モーメントIに比例する
　→ 材料の「強度（降伏点・圧縮強度）」には依存しない点に注意
・座屈長さ係数：両端ピン1.0／両端固定0.5／一端固定他端自由2.0／一端固定他端ピン0.7
・座屈長さが同じでも、Iが大きい（断面が大きい）部材ほど座屈しにくい

【図解】座屈荷重の比較計算の型
　例：同一断面・同一材料で長さと支持条件が異なる柱A・B
　　柱A：両端ピン・長さL　　　→ lk＝1.0L → Pcr∝1/L²
　　柱B：両端固定・長さ2L　　 → lk＝0.5×2L＝1.0L → Pcr∝1/L²
　⇒ 座屈長さlkが等しければ座屈荷重は等しい
○「実長」ではなく「座屈長さ」に換算してから比較するのが鉄則

━━━━━━━━━━━━━━━━━━━━━━
🔑 地震層せん断力の計算
━━━━━━━━━━━━━━━━━━━━━━
・地震層せん断力 Qi＝Ci×Wi（Wi：その層より上の重量）
・地震層せん断力係数 Ci＝Z×Rt×Ai×Co
　Z：地震地域係数（地域により1.0〜0.7）
　Rt：振動特性係数（建物の固有周期と地盤で決まる。1.0以下）
　Ai：層せん断力分布係数（最下層1.0、上層ほど大きい）
　Co：標準せん断力係数
・一次設計（許容応力度計算）：Co＝0.2以上
・保有水平耐力計算（二次設計）：Co＝1.0以上

【図解】Aiの分布イメージ（上ほど大きい）
　・Aiは1階を1.0とし、上の階へいくほど大きくなる（R階＞3階＞2階＞1階=1.0）。
　・棒の長さで表すとR階が最も長く、1階が最も短い階段状になる。
　・上層ほど揺れが増幅されることを表す。
⇒ただし層せん断力Qi自体は下階ほど大きい（上階の重量が累積するため）
⚠「Aiが大きい＝Qiが大きい」ではない点がひっかけどころ

━━━━━━━━━━━━━━━━━━━━━━
🔑 音圧レベルの合成（デシベル計算）
━━━━━━━━━━━━━━━━━━━━━━
・音圧レベル（dB）は対数尺度であり、単純な足し算・掛け算はできない
・同じレベルの音源を2つ重ねると、エネルギーは2倍になるが、
　レベルは約＋3dBの上昇にとどまる
・同じレベルの音源4つ＝2倍×2倍→約＋6dB、10個で＋10dB
・音源の数が2倍になっても、レベルが2倍になるわけではない点に注意

【図解】dB合成の早見表
　同レベル音源の数　　1　　2　　4　　8　　10
　レベルの上昇量　　　0　＋3　＋6　＋9　＋10（dB）
→「2倍ごとに＋3dB」「10倍で＋10dB」の2つだけで全て導ける

━━━━━━━━━━━━━━━━━━━━━━
🔑 照明・色の指標（計算関連の周辺知識）
━━━━━━━━━━━━━━━━━━━━━━
・平均演色評価数（Ra）：色の再現性を表す指標（100に近いほど自然）
・色温度（K）：光の色味。高いほど青白く、低いほど赤みを帯びる
　→ RaとKは別の概念（混同させる出題あり）
・照度（lx）は距離の2乗に反比例する（点光源）

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「座屈荷重は座屈長さに反比例」→誤り。座屈長さの「2乗」に反比例
×「強度の高い鋼材を使えば座屈荷重が増える」→誤り。EとIで決まる
×「Coは一次設計で1.0」→誤り。一次設計0.2、保有水平耐力計算で1.0
×「Aiは下層ほど大きい」→誤り。上層ほど大きい（Qiは下層ほど大きい）
×「音源2つで6dB上昇」→誤り。約3dB上昇

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★Pcr＝π²EI/lk²：E・Iに比例、lk²に反比例、強度は無関係
★Ci＝Z・Rt・Ai・Co、一次設計Co＝0.2・二次設計Co＝1.0
★Ai：上層ほど大／Qi：下層ほど大
★音源2倍＋3dB・10倍＋10dB／照度は距離の2乗に反比例
★Ra＝演色性、K＝色温度（別概念）

━━━━━━━━━━━━━━━━━━━━━━
🔑 深掘り：荷重の種類と特性
━━━━━━━━━━━━━━━━━━━━━━
・固定荷重：建築物自体の重さ（構造体・仕上材等）による、
　常に作用し続ける荷重
・積載荷重：家具・什器・人間等、室の用途に応じて
　変動しうる荷重。事務室・住宅・劇場等、
　用途によって想定値が異なる
・積雪荷重：積雪の重さによる荷重で、
　積雪量（積雪の単位重量×垂直積雪量）に応じて算定される
・地震力・風圧力：地震・風による水平方向の力で、
　建物の高さ・形状・地域係数等に応じて算定される
　（gaku-10のCi＝Z・Rt・Ai・Coはこの地震力の算定式）
・荷重の組み合わせ：一次設計では、常時荷重に
　積雪・地震・風等を組み合わせて検討する

【図解】荷重の分類（常時か一時か）
・常時荷重：固定荷重・積載荷重
・一時的な荷重：積雪荷重・地震力・風圧力
→常時荷重には長期許容応力度、一時的な荷重を含む検討には
　短期許容応力度を用いる（gaku-02の深掘り参照）`,
