        body: `▼ゼロから　集団規定とは
集団規定は「まちの中で建築物同士がどう共存するか」を定める規定です。
単体規定（1つの建物の安全性）とは別に、用途地域・容積率・斜線制限など
「周りとの関係」を扱います。都市計画法とセットで理解しましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 用途地域
━━━━━━━━━━━━━━━━━━━━━━
・用途地域は全13種類：住居系8（第一種・第二種低層住居専用地域、
　田園住居地域、第一種・第二種中高層住居専用地域、第一種・第二種住居地域、
　準住居地域）、商業系2（近隣商業地域・商業地域）、
　工業系3（準工業地域・工業地域・工業専用地域）
・用途地域ごとに建てられる建築物の用途、建蔽率・容積率の上限が指定される
・第一種低層住居専用地域は住宅系の中で最も用途制限が厳しい地域

【図解】用途地域13種類の分類
・住居系（8）：低層専用×2・田園住居・中高層専用×2・住居×2・準住居
・商業系（2）：近隣商業・商業
・工業系（3）：準工業・工業・工業専用
→工業専用地域だけは住宅を建てられない特殊な地域

━━━━━━━━━━━━━━━━━━━━━━
🔑 斜線制限
━━━━━━━━━━━━━━━━━━━━━━
・道路斜線制限：前面道路の反対側境界線から一定の勾配で建築物の
　高さを制限（すべての用途地域に適用）
・隣地斜線制限：隣地境界線から一定の高さ立ち上げた上で勾配制限
　（低層住居専用地域・田園住居地域には適用されない＝絶対高さ制限があるため）
・北側斜線制限：北側の隣地の日照確保のための制限で、
　低層住居専用地域・田園住居地域・中高層住居専用地域のみに適用
・日影規制：中高層建築物が周囲に落とす日影の時間を制限する規定

【図解】斜線制限が適用される地域の違い
｜適用地域｜道路斜線｜隣地斜線｜北側斜線｜
｜低層住居専用・田園｜○｜×｜○｜
｜中高層住居専用｜○｜○｜○｜
｜その他の用途地域｜○｜○｜×｜
⇒低層住居系は絶対高さ制限があるため隣地斜線は適用されない

━━━━━━━━━━━━━━━━━━━━━━
🔑 防火地域・準防火地域
━━━━━━━━━━━━━━━━━━━━━━
・防火地域・準防火地域は市街地の火災の危険を防除するため都市計画で指定
・防火地域内では規模に応じ耐火建築物等または準耐火建築物等とする義務がある
・準防火地域は防火地域より規制がやや緩やかだが、一定規模超は耐火建築物等が必要
・建築物が防火地域・準防火地域にまたがる場合は、原則として
　厳しい方（防火地域）の規定が建築物全体に適用される

━━━━━━━━━━━━━━━━━━━━━━
🔑 建築確認と手続きの流れ
━━━━━━━━━━━━━━━━━━━━━━
・建築確認：建築主事または指定確認検査機関が、計画が法令に適合するか審査
・都市計画区域・準都市計画区域内では、原則としてすべての建築物の
　新築等に建築確認が必要
・開発許可制度：一定規模以上の開発行為（宅地造成等）に都道府県知事等の許可が必要
・接道義務：建築物の敷地は原則として幅員4m以上の道路に2m以上接する

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「隣地斜線制限はすべての用途地域に適用される」→誤り。低層住居専用・
　田園住居地域には適用されない
×「北側斜線制限は商業地域にも適用される」→誤り。住居系の一部地域のみ
×「防火・準防火地域にまたがる場合は緩い方の規定による」→誤り。
　原則厳しい方（防火地域）が適用
×「工業専用地域には住宅を建てられる」→誤り。住宅は建築不可
×「接道義務は幅員4m以上の道路に4m以上接すること」→誤り。接する長さは2m以上

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★用途地域は13種類（住居系8・商業系2・工業系3）
★北側斜線＝住居系の一部地域のみ／隣地斜線＝低層住居系は適用外
★防火・準防火にまたがる場合は厳しい方（防火地域）が全体に適用
★接道義務：幅員4m以上の道路に2m以上接する
★工業専用地域だけは住宅を建てられない

━━━━━━━━━━━━━━━━━━━━━━
🔑 深掘り：容積率・建蔽率の算定
━━━━━━━━━━━━━━━━━━━━━━
・建蔽率＝建築面積／敷地面積×100（建物を
　真上から見たときの敷地に対する割合）
・容積率＝延べ面積／敷地面積×100（各階の
　床面積の合計の敷地に対する割合）
・角地緩和：一定の条件を満たす角地では、
　建蔽率の限度が緩和される場合がある
・防火地域内の耐火建築物等：建蔽率の限度が
　緩和される場合がある

【図解】建蔽率と容積率の違い
・建蔽率：建築面積／敷地面積（真上から見た割合）
・容積率：延べ面積／敷地面積（各階合計の割合）
⇒「1階だけの広がり」が建蔽率、「積み上げた総量」が容積率`,
