　省エネ性とBCP（非常時のバックアップ）の
　両立を図る狙いで採用されることがある

【図解】熱源選定の主な検討軸
・省エネ性：COP・一次エネルギー消費量
・BCP（事業継続）：停電時等の稼働継続性
・インフラ条件：電力・ガス供給の状況
