        body: `▼ゼロから　二段階設計法の全体像
gaku-10で学んだCi＝Z・Rt・Ai・Coの一次設計に続き、ここでは
大地震を想定した二次設計（保有水平耐力計算）を整理します。
「粘り強い構造ほど割増しなしで済む」という発想が核心です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 二段階設計法の全体像
━━━━━━━━━━━━━━━━━━━━━━
・一次設計：中規模の地震（Co＝0.2程度）を想定し、許容応力度計算により
　部材が損傷しないことを確認する
・二次設計：大規模の地震（Co＝1.0相当）を想定し、
　保有水平耐力計算により建物が倒壊しないことを確認する
・二次設計が必要になるのは、一定規模以上の建築物や
　構造計算ルート2・ルート3を適用する建築物等

【図解】一次設計と二次設計の目標の違い
｜設計段階｜想定する地震｜目標｜
｜一次設計｜中規模地震（Co=0.2）｜部材が損傷しない｜
｜二次設計｜大規模地震（Co=1.0）｜建物が倒壊しない｜
→「壊れない」から「命を守る（倒壊しない）」へと目標水準が変わる

━━━━━━━━━━━━━━━━━━━━━━
🔑 保有水平耐力と必要保有水平耐力
━━━━━━━━━━━━━━━━━━━━━━
・保有水平耐力Qu：建物が実際に保持している水平方向の耐力
・必要保有水平耐力Qun＝Ds・Fes・Qud（各層で計算）
・判定：Qu ≧ Qun であれば、その層は大地震時にも倒壊しないと判断される
・Ds（構造特性係数）：建物の靭性（粘り強さ）を表す係数。
　塑性変形能力が大きい（粘り強い）構造ほど小さい値、
　脆性的な破壊をする構造ほど大きい値となる
・Fes（形状係数）：剛性率・偏心率の悪さを表す係数。
　剛性率が低い（弱い層がある）、偏心率が大きい（ねじれやすい）ほど
　Fesは大きくなり、必要保有水平耐力の要求が厳しくなる

【図解】Ds値の考え方
　粘り強い構造（靭性大）　←────→　脆性的な構造（靭性小）
　Ds小さい（0.3程度）　　　　　　　Ds大きい（0.55程度）
　＝必要保有水平耐力が小さくて済む　＝必要保有水平耐力が大きくなる
→「粘れば粘るほど、要求される強さの割増しは少なくて済む」

━━━━━━━━━━━━━━━━━━━━━━
🔑 強柱弱梁の原則
━━━━━━━━━━━━━━━━━━━━━━
・塑性ヒンジ（部材が降伏し曲がる箇所）が梁に先行して生じる
　「全体崩壊型（梁降伏先行型）」は、多数の梁で分散してエネルギーを
　吸収できるため望ましい崩壊形とされる
・柱に塑性ヒンジが先行する「層崩壊型（柱降伏先行型）」は、
　特定の層に変形が集中し倒壊に至りやすいため避けるべき崩壊形とされる
・この考え方から「柱を梁より強く設計する（強柱弱梁）」ことが
　耐震設計上望ましいとされる

【図解】崩壊形の比較（望ましい／望ましくない）
・全体崩壊型（梁降伏）：○多数の梁で分散してエネルギー吸収
・層崩壊型（柱降伏）：×特定層に変形集中→倒壊しやすい
⇒強柱弱梁：柱は梁より強くし、先に梁が降伏するように設計する

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「Ds値は靭性が大きいほど大きくなる」→誤り。靭性が大きいほど
　Ds値は小さくなる
×「一次設計は大規模地震を想定した検討である」→誤り。
　一次設計は中規模地震（二次設計が大規模地震）
×「柱降伏先行型が望ましい崩壊形である」→誤り。
　梁降伏先行型（全体崩壊型）が望ましい
×「Fesは剛性率・偏心率が良好なほど大きくなる」→誤り。
　悪いほど（剛性率低い・偏心率大きい）Fesは大きくなる
×「保有水平耐力はQu＜Qunであれば安全と判定される」→誤り。
　Qu≧Qunで安全と判定される

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★一次設計＝中規模地震・許容応力度／二次設計＝大規模地震・保有水平耐力
★Qu≧Qun＝Ds・Fes・Qudで倒壊しないと判定
★Ds：靭性大→小さい値／脆性的→大きい値
★Fes：剛性率低い・偏心率大きいほど大きい値（不利）
★強柱弱梁＝梁降伏先行型（全体崩壊型）を狙う設計`,
