・ウレタン塗膜防水：補強布を用いて所定厚さを確保
・脱気装置：下地の水蒸気を排出し防水層のふくれを防止する
・シーリング：ワーキングジョイントは2面接着（ボンドブレーカー使用）
　プライマー塗布後、当日中にシーリング材を充填

【図解】アスファルト防水の張り方の原則
　水上（高い側）
　　▔▔▔▔▔▔▔←後に張る
　　　▔▔▔▔▔▔▔▔←重ね100mm以上
　　　　▔▔▔▔▔▔▔▔▔←先に張る
