○水下から水上へ張り上げる＝重ね目が水の流れに逆らわない
×水上から張ると重ね目に水が入り込む向きになる

【図解】シーリングの2面接着と3面接着
　ワーキングジョイント（動く目地）＝2面接着
　　目地の両側面だけにシーリング材を接着し、目地底にはボンドブレーカーを入れて縁を切る
　　⇒ムーブメントに追従できる
　ノンワーキングジョイント（動かない目地）＝3面接着
　　⇒目地底にも接着させ水密性を優先
⚠動く目地を3面接着にすると追従できず破断する（最頻出）

