　タイル張り用振動機で埋め込むように張る。上から下へ一段おきに張り進める
・改良圧着張り：下地とタイル裏面の両方に張付けモルタルを塗って張る
・改良積上げ張り：タイル裏面にモルタルを塗り下から上へ積み上げる
・接着剤張り：内装向き（外装は原則モルタル系）
・張付けモルタルの1回の塗付け面積：2m²以下かつ60分以内に
