・まぐさ・庇先端等の剥落危険部位には剥落防止対策を検討する

【図解】タイル張り工法の比較
工法｜モルタルを塗る場所｜張る方向
密着張り｜下地側（2層）＋振動機｜上から下
改良圧着張り｜下地側＋タイル裏面の両方｜上から下
改良積上げ張り｜タイル裏面｜下から上
⇒「改良積上げだけ下から上」が覚えどころ

