×「エポキシ樹脂は高圧で素早く注入」→誤り。低圧でゆっくり
×「あと施工アンカーは主筋に当たっても構わず穿孔」→誤り。探査してかわす
×「既存塗膜は全面除去が原則」→誤り。活膜は残し劣化部のみ除去

