・外張断熱工法：躯体の外側に断熱材を張り、熱橋（ヒートブリッジ）を防ぎやすい
・防湿層：断熱材の室内側（高温高湿側）に設けるのが原則
・硬質ウレタンフォーム吹付け工法：厚さをピン等で確認しながら施工、
