【図解】マスコンクリートの温度ひび割れ
　断面で見ると、外側が表面、その内側が内部。
　・内部：水和熱で高温になり膨張する
　・表面：外気に冷やされて縮む
　・内部の膨張を縮もうとする表面が拘束するため表面に引張が生じ、表面にひび割れが発生する
→内外温度差が大きいほど危険。だから表面を「保温」して差を縮める
×「表面を冷やして温度を下げる」は温度差を拡大させる誤り

