        emoji: '☣️',
        body: `▼ゼロから　設備改修とアスベスト対策
配管の更新・更生と、既存建材に含まれるアスベスト（石綿）対策は、
どちらも改修工事で頻出のテーマです。飛散性のレベル分けを
軸に理解しましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 給排水配管の改修工法
━━━━━━━━━━━━━━━━━━━━━━
・更新工法：既存の配管を撤去し、新規の配管に取り替える工法。
　性能は確実に更新できるが、はつり等の手間・工期がかかる
・更生工法：既存配管を存置したまま、管内に樹脂ライニング等を
　施し性能を回復させる工法。はつりを伴わず騒音・振動を抑えられる
・さや管工法：既存配管の外側にさや管を新設し、その中に
　新しい配管を通す工法（床下・共用部の配管更新等で用いられる）
・改修方式の選定は、更新の緊急度・使用継続の必要性・
　コストを踏まえて総合的に判断する

【図解】更新工法と更生工法の違い
・更新工法：既存配管を撤去し新規に取替え・確実
・更生工法：既存管を存置し内面をライニング
→更生工法は「居ながら」改修に向くが、更新工法ほどの
　性能回復は保証されない場合もある

━━━━━━━━━━━━━━━━━━━━━━
🔑 アスベスト含有建材のレベル分類
━━━━━━━━━━━━━━━━━━━━━━
・レベル1：吹付けアスベスト等。発じん性が最も高く、
　除去作業では最も厳重な飛散防止措置が求められる
・レベル2：保温材・耐火被覆材等（配管の保温材等）。
　レベル1に次いで発じん性が高い
・レベル3：成形板等（スレート板等、比較的発じん性が低い建材）。
　レベル1・2に比べ規制の程度はやや緩やかだが、
　除去作業自体の対策は必要
・事前調査：解体・改修工事の着手前にアスベスト含有の有無を
　調査し、記録を保存する義務がある

【図解】アスベストレベルと飛散性
　発じん性　高い　←──────────→　低い
　　　　　レベル1　　レベル2　　　　レベル3
　　　　　（吹付け材）（保温材等）　（成形板等）
⇒レベルの数字が小さいほど発じん性が高く、規制が厳しい

━━━━━━━━━━━━━━━━━━━━━━
🔑 アスベスト除去作業の管理
━━━━━━━━━━━━━━━━━━━━━━
・隔離養生：作業区画をシート等で隔離し、外部への飛散を防止する
・負圧集じん機：作業区画内の気圧を外部より低く（負圧に）保つことで、
　隙間からの粉じんの流出を防ぐ
・前室の設置：作業区画と外部の間に前室を設け、
　作業員の出入りの際の粉じん持ち出しを抑制する
・石綿作業主任者：アスベストを取り扱う作業では選任が義務付けられ、
　作業員への特別教育の実施も必要となる

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「レベル1は成形板等の低発じん性建材である」→誤り。
　レベル1は吹付け材で最も発じん性が高い
×「更生工法は既存配管を撤去してから行う」→誤り。
　既存配管を存置したまま内面を処理する工法
×「作業区画内は外部より高い気圧（正圧）に保つ」→誤り。
　外部より低い気圧（負圧）に保ち粉じんの流出を防ぐ
×「アスベスト事前調査は工事着手後に行えばよい」→誤り。
　着手前に実施し記録を保存する義務がある
×「レベル3の建材は対策を行わずに除去できる」→誤り。
　規制の程度は緩やかでも除去作業自体の対策は必要

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★更新工法＝取替え／更生工法＝ライニングで性能回復（居ながら向き）
★アスベストレベル：1（吹付け材）＞2（保温材）＞3（成形板）の順に発じん性高
★作業区画は負圧に保ち、前室で粉じん持出しを防止
★石綿作業主任者の選任・特別教育が義務
★事前調査は着手前に実施し記録を保存する`,
