・外張り断熱工法：構造体の外側を断熱材で連続して覆う工法で、
　熱橋が生じにくい

【図解】断熱施工での性能低下の原因
・熱橋（ヒートブリッジ）：柱・梁部分等で断熱が途切れる箇所
・気密層の隙間：シート重ね部・貫通部の施工不良
・断熱材の圧縮・隙間：施工精度不足による性能低下
⇒「設計上のUA値」と「実際の施工後の性能」を一致させるのが施工管理の役割

━━━━━━━━━━━━━━━━━━━━━━
