        emoji: '🪟',
        body: `▼ゼロから　カーテンウォール工事の要点
sekou-06で学んだPCa・カーテンウォールの基礎を発展させ、
ここでは取付け方式・目地・ガラスの熱割れ対策を扱います。
「動きにどう追従させるか」がカーテンウォール工事の共通テーマです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 ファスナー（取付け金物）方式
━━━━━━━━━━━━━━━━━━━━━━
・ロッキング方式：パネルの上下2点を回転可能な支持点とし、
　地震時の層間変位にパネルが「回転」して追従する方式
・スライド方式：パネルの支持点の一方を可動（スライド可能）とし、
　層間変位にパネルが「滑って」追従する方式
・いずれの方式も、躯体の変形をカーテンウォールにそのまま
　伝えず、追従させることで損傷を防ぐのが目的
・ファスナーの取付け孔は、施工誤差を吸収できるよう
　長孔等の調整代を設けることが多い

【図解】ロッキング方式とスライド方式
・ロッキング方式：パネルが回転して層間変位に追従
・スライド方式：支持点が滑って層間変位に追従
→どちらも「躯体の変形をパネルに直接伝えない」ための工夫

━━━━━━━━━━━━━━━━━━━━━━
🔑 目地のシーリング
━━━━━━━━━━━━━━━━━━━━━━
・ワーキングジョイント：温度変化や層間変位により目地の
　挙動（伸縮）が大きい部位の目地。2面接着とし、
　バックアップ材でシーリング材の3面接着を避ける
・ノンワーキングジョイント：挙動がほとんど生じない目地。
　3面接着とすることができる
・2面接着とする理由：シーリング材が底面にも接着すると、
　伸縮時に底面から引き裂かれるような応力が生じ、
　早期破断につながるため
・シーリング材の打継ぎ：既存シーリングの劣化更新（打替え）では、
　既存シーリング材を完全に除去してから新規に打設する

【図解】2面接着と3面接着
　ワーキングジョイント（挙動大）：目地の両側面のみに接着させる（2面接着）。
　目地底にはバックアップ材を入れて底面の接着を絶つ
　ノンワーキングジョイント（挙動小）：両側面＋底面も接着可（3面接着）
⇒挙動が大きいほど「底面を切り離す」のが原則（2面接着）

━━━━━━━━━━━━━━━━━━━━━━
🔑 ガラスの取付けと熱割れ対策
━━━━━━━━━━━━━━━━━━━━━━
・グレイジングガスケット：ガラスをはめ込む溝にゴム等の
　ガスケットを用い、水密性・気密性を確保しつつガラスの
　変形・振動を緩衝する工法
・構造シーラント構法（SSG構法）：金属枠を用いず、
　構造用シーラントでガラスを支持構造に接着する工法。
　外観をフラットに仕上げられる
・熱割れ：ガラスの日射を受ける中央部と、
　サッシで覆われ日射を受けにくい周縁部との温度差により
　ひび割れが生じる現象。網入りガラスは鉄線部分に応力が
　集中しやすく特に注意が必要
・熱割れ対策：日射熱を吸収しやすい色付きガラスや
　厚いガラスでは温度差が生じやすいため、周辺環境（庇・
　ブラインド等による部分日陰）にも配慮した設計とする

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「ワーキングジョイントは3面接着とする」→誤り。
　2面接着としバックアップ材で底面接着を避ける
×「スライド方式はパネルが回転して追従する方式である」→誤り。
　回転して追従するのはロッキング方式
×「網入りガラスは熱割れが生じにくい」→誤り。
　鉄線部分に応力が集中しやすく、熱割れに特に注意が必要なガラス
×「SSG構法は金属枠でガラスを支持する工法である」→誤り。
　構造用シーラントで接着し金属枠を用いない（または最小化する）工法
×「シーリング材の打替えは既存の上に重ねて打設する」→誤り。
　既存シーリング材を完全に除去してから新規に打設する

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★ロッキング方式＝回転で追従／スライド方式＝滑って追従
★ワーキングジョイント＝2面接着（バックアップ材で底面を切る）
★ノンワーキングジョイントは3面接着可
★熱割れは中央部と周縁部（サッシ被覆部）の温度差が原因
★SSG構法は構造用シーラントでガラスを接着しフラットな外観に`,
