        body: `▼ゼロから　工程管理とは
工程管理は「工期どおりに終わらせる技術」です。
そのための道具が工程表。特にネットワーク工程表は
「どの作業が遅れると全体が遅れるか（クリティカルパス）」を
見える化できるのが最大の強みで、計算問題も出題されます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 工程表の種類と特徴
━━━━━━━━━━━━━━━━━━━━━━
・バーチャート：作成が容易で各作業の期間が分かりやすい。
　作業間の関連・重点管理作業は把握しにくい
・ガントチャート：達成率(%)を表示。所要日数・相互関係は不明
・ネットワーク工程表：作業の相互関係・クリティカルパスが明確。
　作成に熟練を要する
・出来高累計曲線（Sカーブ）：工事全体の進捗を金額ベースで管理
　バナナ曲線（上方・下方許容限界）内に収める

【図解】工程表の比較
種類｜作成｜相互関係｜進捗把握
バーチャート｜○容易｜×不明確｜△
ガントチャート｜○容易｜×不明｜○達成率のみ
ネットワーク｜×熟練要｜◎明確｜◎重点把握可
Sカーブ｜○｜×｜◎全体出来高
⇒長所短所の入替え出題が定番。「簡単なものは関係が見えない」

━━━━━━━━━━━━━━━━━━━━━━
🔑 ネットワーク手法の用語
━━━━━━━━━━━━━━━━━━━━━━
・アクティビティ（→）：作業。矢線の長さは所要時間と無関係
・イベント（○）：作業の結合点
・ダミー（--→）：架空作業。所要時間ゼロ、作業の順序関係のみ示す
・最早開始時刻（EST）：その作業を最も早く開始できる時刻
　→ 前進計算（複数経路が合流する場合は「最大値」）
・最遅完了時刻（LFT）：工期に影響しない範囲で最も遅く完了してよい時刻
　→ 後退計算（分岐する場合は「最小値」）
・フロート（余裕時間）
　トータルフロート（TF）＝ 最遅完了時刻 −（最早開始時刻＋所要日数）
　フリーフロート（FF）：後続作業の最早開始に影響しない余裕
　FF ≦ TF が常に成り立つ
・クリティカルパス：TF＝0の作業をつないだ最長経路。
　この経路の遅れは直ちに工期の遅れとなる

【図解】ネットワーク計算の手順
　①前進計算：スタートから右へ、ESTを計算
　　　合流点では「大きい方」を採用（遅い方に合わせる）
　②後退計算：ゴールから左へ、LFTを計算
　　　分岐点では「小さい方」を採用（早い方に合わせる）
　③TF＝LFT−（EST＋所要日数）
　④TF＝0をつなぐ＝クリティカルパス（最長経路）
⚠合流＝最大値・分岐＝最小値。逆にすると全て間違える

【図解】フロートのイメージ
　作業A（3日）と作業B（5日）は並行して進み、
　両方が終わってから作業Cを開始する
　Aは2日遅れてもCの開始に影響しない → Aのフリーフロート＝2日
　クリティカルパス上の作業＝フロート0（1日も遅れられない）
→TFを使い切ると後続作業のTFが減る（FFなら影響なし）

━━━━━━━━━━━━━━━━━━━━━━
🔑 工期短縮・進捗管理
━━━━━━━━━━━━━━━━━━━━━━
・工期短縮はクリティカルパス上の作業を対象に検討する
　（クリティカルパス以外を短縮しても工期は縮まない）
・山積み・山崩し：作業員・機械の平準化（山崩しは余裕時間を利用）
・突貫工事はコスト増（直接費増）と品質低下のリスク
・工程・原価・品質の関係：工程を極端に速めても遅らせても原価は増加する
　（最適工期で原価最小）
・進捗に遅れが生じた場合：残作業の作業能率を上げる、
　並行作業化・作業班の増強等を検討する

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「バーチャートは作業間の関連が明確」→誤り。関連は把握しにくい
×「矢線の長さは所要時間に比例させる」→誤り。無関係
×「ESTの合流は最小値をとる」→誤り。最大値（LFTの分岐が最小値）
×「ダミーには所要時間がある」→誤り。時間ゼロ・順序関係のみ
×「工期短縮はどの作業を縮めてもよい」→誤り。クリティカルパス上の作業
×「TF＞FFとなることはない」→誤り。常にFF≦TF（TFの方が大きいか等しい）

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★前進計算＝合流で最大／後退計算＝分岐で最小
★TF＝LFT−（EST＋D）、FF≦TF、クリティカルパス＝TF0の最長経路
★ダミー＝時間ゼロの順序表示
★工期短縮＝クリティカルパスを攻める
★最適工期＝総原価（直接費＋間接費）最小の工期

━━━━━━━━━━━━━━━━━━━━━━
🔑 深掘り：バーチャートとネットワーク工程表の使い分け
━━━━━━━━━━━━━━━━━━━━━━
・バーチャート（ガントチャート）：縦軸に作業名、
　横軸に時間をとり、各作業の開始〜終了を横棒で表す工程表。
　視覚的に分かりやすく、進捗の把握が容易
・バーチャートの弱点：作業相互の関連性（先行・後続関係）が
　表現しにくく、どの作業が全体工期を左右するか
　（クリティカルパス）が読み取りにくい
・ネットワーク工程表：作業相互の関連性を矢線・結合点で
　明示できるため、クリティカルパスや各作業のフロートを
　定量的に把握できる
・実務では、全体像の把握にはバーチャート（またはガントチャートに
　工程バーを重ねたもの）、詳細な工程分析にはネットワーク工程表を
　併用することが多い

【図解】バーチャートとネットワーク工程表の比較
・バーチャート：視覚的に分かりやすい・関連性が不明瞭
・ネットワーク工程表：関連性・クリティカルパスが明確
→「分かりやすさ」と「分析力」はトレードオフの関係にあり、
　目的に応じて使い分ける、または併用するのが実務的`,
