　環境負荷の少ない資材（再生材料を用いた製品等）を
　優先的に選定する取組み

【図解】環境負荷低減策の分類
・機械・稼働の工夫：低公害型建機・アイドリングストップ
・資源の有効利用：発生土の再利用・グリーン調達
→「機械の使い方を工夫する」と「資材・資源の使い方を工夫する」の
