        body: `▼ゼロから　改修工事管理の特殊性
新築工事と違い、改修工事は「使いながら」「既存を活かしながら」
工事を進める点が最大の特徴です。事前調査の精度と、
発注者・使用者との調整力が管理者の腕の見せどころになります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 居ながら改修の計画
━━━━━━━━━━━━━━━━━━━━━━
・居ながら改修：建物の使用を継続したまま行う改修工事。
　仮設間仕切り・防音養生・粉じん対策等で利用者への影響を最小化する
・工程分割：フロア・区画ごとに工事範囲を区切り、
　順次施工することで使用を継続しながら全体を改修する
・時間帯調整：騒音・振動を伴う作業は、利用者の少ない時間帯
　（夜間・休日等）に計画することが多い
・仮設計画：仮設トイレ・仮設動線等、利用者の生活・業務に
　支障が出ないよう代替設備を用意する

【図解】居ながら改修の区画分割イメージ
　建物全体をA区画・B区画・C区画に分割する
　A区画＝施工中、B区画＝使用中、C区画＝使用中
　→A完了後、B区画へ順次移行
⇒同時に全館を止めず、区画ごとに「工事」と「使用」を両立させる

━━━━━━━━━━━━━━━━━━━━━━
🔑 発注者・使用者との調整
━━━━━━━━━━━━━━━━━━━━━━
・工事説明会：着工前に利用者・近隣に工事内容・期間・
　影響（騒音・振動・動線変更等）を説明する
・掲示：工事範囲・迂回経路・注意事項を分かりやすく掲示し、
　利用者の安全確保と混乱防止を図る
・クレーム対応：改修工事は使用者から近い距離で行われるため、
　苦情・要望への迅速な対応体制を整えておく
・工程調整会議：発注者・使用者側の行事・繁忙期等を踏まえ、
　定期的に工程の調整を行う

━━━━━━━━━━━━━━━━━━━━━━
🔑 事前調査と既存図面の確認
━━━━━━━━━━━━━━━━━━━━━━
・既存図面と現況の差異確認：竣工後の増改築・修繕により、
　既存図面と実際の状況が異なっている場合があるため、
　現地調査で実態を確認することが重要
・躯体の劣化状況調査：コンクリートの中性化深さ、
　鉄筋の腐食状況等を事前に把握し、補修範囲・工法を決定する
・アスベスト事前調査：解体・改修工事の着手前に実施し、
　結果を記録・保存する義務がある（対象規模等の要件を満たす場合は
　都道府県等への報告も必要）

【図解】改修工事の計画プロセス
　既存図面確認 → 現地調査（差異・劣化・アスベスト等）
　　↓
　調査結果を踏まえた工法・工程の検討
　　↓
　発注者・使用者との調整（説明会・掲示）
　　↓
　居ながら施工計画の確定（区画分割・時間帯調整）
→新築より「調査」と「調整」に多くの時間を要するのが改修工事の特徴

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「改修工事は既存図面のみで計画すればよい」→誤り。
　現地調査による実態確認が不可欠
×「居ながら改修では全館を一斉に施工するのが基本」→誤り。
　区画ごとに順次施工するのが基本
×「アスベスト事前調査は工事中に行えばよい」→誤り。
　着手前に実施し記録を保存する義務がある
×「騒音を伴う作業は利用者の多い時間帯に行うのが望ましい」→誤り。
　利用者の少ない時間帯に計画するのが基本
×「工事説明会は近隣には行わなくてよい」→誤り。
　利用者だけでなく近隣への説明も重要

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★居ながら改修は区画分割＋時間帯調整で使用と工事を両立
★既存図面と現況の差異は現地調査で必ず確認
★アスベスト事前調査は着手前・記録保存が義務
★工事説明会・掲示で利用者・近隣とのトラブルを予防
★改修工事は新築より「調査」と「調整」の比重が大きい`,
