        id: 'kanri-15',
        title: '工程管理の応用（ネットワーク工程表の詳細計算）',
        emoji: '🗓️',
        body: `▼ゼロから　ネットワーク工程表の計算
kanri-02で学んだ工程管理の基礎から、ここでは
最早・最遅時刻の計算とフロートの求め方を扱います。
「前から積み上げ、後ろから逆算する」の2方向計算が核心です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 最早時刻と最遅時刻
━━━━━━━━━━━━━━━━━━━━━━
・最早開始時刻（EST）：先行作業がすべて完了した時点で、
　その作業を開始できる最も早い時刻
・最早終了時刻（EFT）＝EST＋作業日数
・最遅開始時刻（LST）：工期全体に遅れを生じさせずに、
　その作業を開始できる最も遅い時刻
・最遅終了時刻（LFT）＝LST＋作業日数
・計算の順序：ESTは始点から終点に向かって（前進計算）、
　LSTは終点から始点に向かって（後進計算）で求める

【図解】前進計算と後進計算
　始点 →→→→→→→→→→→→ 終点
　　　（前進計算：ESTを積み上げる）
　始点 ←←←←←←←←←←←← 終点
　　　（後進計算：LSTを逆算する）
→両方向から計算して初めてフロート（余裕）が求まる

━━━━━━━━━━━━━━━━━━━━━━
🔑 フロート（余裕時間）
━━━━━━━━━━━━━━━━━━━━━━
・トータルフロート（TF）＝LFT−EFT（またはLST−EST）
　→ その作業が工期全体に影響を与えずに遅らせられる余裕時間
・フリーフロート（FF）＝後続作業のEST−自作業のEFT
　→ その作業が後続作業の最早開始に影響を与えずに
　　 遅らせられる余裕時間
・関係：FF ≦ TF が常に成立する
　（フリーフロートはトータルフロートの内数）
・クリティカルパス：TF＝0の作業が始点から終点まで
　連続する経路。この経路の遅れがそのまま工期の遅れになる

【図解】TFとFFの関係
　TF（トータルフロート）は2つの部分から成る
　・FF（フリーフロート）：後続作業の最早開始に影響しない部分
　・依存フロート：使うと他作業のフロートに影響する部分
⇒FFはTFの一部（FF≦TFは必ず成立する）

━━━━━━━━━━━━━━━━━━━━━━
🔑 クリティカルパスの特定
━━━━━━━━━━━━━━━━━━━━━━
・クリティカルパス上の作業は、1日でも遅れると
　工期全体がそのまま遅れるため、重点的な進捗管理の対象となる
・クリティカルパスは複数存在する場合がある
　（並行する経路のTFがともに0になる場合等）
・工期短縮を検討する際は、クリティカルパス上の作業を
　短縮しなければ全体の工期は短縮できない
　（クリティカルパス以外をいくら短縮しても効果はない）

【図解】工期短縮の考え方
　クリティカルパス上の作業を短縮 → 工期短縮に直結
　クリティカルパス以外の作業を短縮 → 工期は変わらない（フロートが減るだけ）
⇒工期短縮の検討はまずクリティカルパスの特定から始める

━━━━━━━━━━━━━━━━━━━━━━
🔑 山積み・山崩し
━━━━━━━━━━━━━━━━━━━━━━
・山積み：各作業に必要な労務・資機材の投入量を、
　工程表に沿って積み上げ、日ごとの必要量を可視化すること
・山崩し（平準化）：フロートを活用して作業の開始時期を
　調整し、労務・資機材の投入量の山（ピーク）をならすこと
・クリティカルパス上の作業はフロートがないため、
　山崩しの対象にはできない（動かすと工期が延びるため）

━━━━━━━━━━━━━━━━━━━━━━
⚠ ひっかけ注意
━━━━━━━━━━━━━━━━━━━━━━
×「ESTは終点から始点に向かって計算する」→誤り。
　始点から終点に向かう前進計算で求める
×「フリーフロートはトータルフロートより大きくなる場合がある」→誤り。
　FF≦TFが常に成立する
×「クリティカルパスは必ず1本しか存在しない」→誤り。
　複数存在する場合がある
×「クリティカルパス以外の作業を短縮すれば工期は必ず短縮できる」→誤り。
　クリティカルパス上を短縮しない限り工期は短縮されない
×「山崩しはクリティカルパス上の作業にも適用できる」→誤り。
　フロートがないため山崩しの対象にはできない

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★EST・EFTは前進計算、LST・LFTは後進計算で求める
★TF＝LFT−EFT、FF＝後続のEST−自分のEFT、FF≦TF
★クリティカルパス＝TF0の作業が連続する経路（複数存在も可）
★工期短縮はクリティカルパス上の作業を縮めない限り実現しない
★山崩しはフロートのある作業のみが対象`,
