・除去作業のレベル分類
　レベル1（吹付け石綿）：発じん性が最も高く、隔離養生・負圧除去装置等の
　　厳重な飛散防止措置が必要
　レベル2（保温材・耐火被覆材等）：原則として隔離して作業する
　レベル3（成形板等）：湿潤化し、手ばらしで撤去する
・除去作業に労働者を従事させる場合は特別教育が必要
・工事の規模等に応じて労働基準監督署長等への届出・報告が必要な場合がある

