・河川法・港湾法等、敷地条件によって関連法規が追加される場合がある
・埋蔵文化財包蔵地での工事は文化財保護法に基づく事前の届出が必要

【図解】健康障害防止規則の共通構造
　事前調査・作業環境の把握（石綿調査・作業環境測定）
