━━━━━━━━━━━━━━━━━━━━━━
・雇入れ時教育は雇用形態を問わず、パート・臨時雇用の労働者にも実施義務がある
・作業内容を変更したときにも同様の教育を行う
・職長教育は建設業を含む一定業種で、新任の職長等に実施義務がある
　（作業主任者は職長教育の対象から除かれる）
・有機溶剤の区分：第1種（赤・最も規制が厳しい）＞第2種（黄）＞第3種（青）
　の順に規制の程度が厳しい（有害性が最も高いのは第1種）
・特殊健康診断は区分にかかわらず6月以内ごとに1回実施する

【図解】安全衛生教育の種類
・雇入れ時教育＝全労働者（パート・臨時も）
・作業内容変更時教育＝雇入れ時と同内容
・特別教育＝危険有害業務ごと（記録3年保存）
・職長教育＝新任職長等（作業主任者は除く）
⇒「パートだから教育不要」は必ず誤り

