　指定確認検査機関にも申請できる
×「構造計算適合性判定はすべての建築物で必要である」→誤り。
　高度な構造計算を要する一定規模以上の建築物が対象
×「検査済証の交付前でも自由に建築物を使用できる」→誤り。
　原則として使用できず、仮使用の認定等の例外的な措置による
×「中間検査に合格しなくても工事を続行できる」→誤り。
　合格しないと特定工程後の工事を原則進められない
×「計画変更があっても再度の確認は不要である」→誤り。
　原則として計画変更の確認を受ける必要がある

