×「資材価格の変動は請負代金に一切反映されない」→誤り。
　変更に関するルールの明確化が進められている
×「週休2日制の推進は民間工事のみを対象とする施策である」→誤り。
　主に公共工事において工期設定・経費計上での後押しが進められている

